<script setup>
import {computed,onMounted,ref,watch} from 'vue'
import {api} from './api'
const props=defineProps({channel:{type:String,default:'telegram'}})
const campaigns=ref([]),accounts=ref([]),selected=ref(null),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const campaignOpen=ref(false),stepOpen=ref(false),editingStep=ref(null)
const form=ref({name:'',description:'',channel_account_id:'',audience_type:'all',scheduled_at:''})
const step=ref({name:'',delay_seconds:0,message_mode:'freeform',message_text:'',parse_mode:'HTML',media_url:'',media_type:'image'})
const channelLabel=computed(()=>props.channel==='telegram'?'Telegram':'WhatsApp')
const activeAccounts=computed(()=>(accounts.value||[]).filter(x=>x.active))
function fmt(v){return v?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—'}
function accountName(a){return props.channel==='telegram'?(a.name||a.username||('Bot '+a.id)):(a.verified_name||a.display_phone_number||('WhatsApp '+a.id))}
function delayLabel(n){n=Number(n||0);if(!n)return 'Immediately';if(n%86400===0)return (n/86400)+' day'+(n===86400?'':'s')+' later';if(n%3600===0)return (n/3600)+' hour'+(n===3600?'':'s')+' later';if(n%60===0)return (n/60)+' minute'+(n===60?'':'s')+' later';return n+' seconds later'}
async function load(){loading.value=true;error.value='';try{accounts.value=props.channel==='telegram'?await api.telegramBots():await api.whatsappConnections();campaigns.value=await api.messagingCampaigns(props.channel);if(selected.value){const found=campaigns.value.find(x=>x.id===selected.value.id);selected.value=found?await api.messagingCampaign(found.id):null}}catch(e){error.value=e.message}finally{loading.value=false}}
function newCampaign(){form.value={name:'',description:'',channel_account_id:activeAccounts.value[0]?.id||'',audience_type:'all',scheduled_at:''};campaignOpen.value=true}
async function saveCampaign(){if(!form.value.name.trim()||!form.value.channel_account_id)return;saving.value=true;error.value='';try{const c=await api.createMessagingCampaign({name:form.value.name.trim(),description:form.value.description||null,channel:props.channel,channel_account_id:Number(form.value.channel_account_id),audience_type:form.value.audience_type,scheduled_at:form.value.scheduled_at||null});campaignOpen.value=false;success.value='Campaign created.';await load();selected.value=await api.messagingCampaign(c.id)}catch(e){error.value=e.message}finally{saving.value=false}}
async function openCampaign(c){selected.value=selected.value?.id===c.id?null:await api.messagingCampaign(c.id)}
function newStep(){editingStep.value=null;step.value={name:'Message '+((selected.value?.steps?.length||0)+1),delay_seconds:0,message_mode:'freeform',message_text:'',parse_mode:'HTML',media_url:'',media_type:'image'};stepOpen.value=true}
function editStep(s){editingStep.value=s.id;step.value={name:s.name,delay_seconds:s.delay_seconds,message_mode:s.message_mode,message_text:s.message_text,parse_mode:s.parse_mode||'HTML',media_url:s.media_url||'',media_type:s.media_type||'image'};stepOpen.value=true}
async function saveStep(){if(!selected.value||!step.value.name.trim()||!step.value.message_text.trim())return;saving.value=true;error.value='';try{const payload={...step.value,name:step.value.name.trim(),delay_seconds:Number(step.value.delay_seconds||0),media_url:step.value.media_url||null,media_type:step.value.media_url?step.value.media_type:null};if(editingStep.value)await api.updateMessagingCampaignStep(selected.value.id,editingStep.value,payload);else await api.addMessagingCampaignStep(selected.value.id,payload);selected.value=await api.messagingCampaign(selected.value.id);campaigns.value=await api.messagingCampaigns(props.channel);stepOpen.value=false;success.value='Campaign step saved.'}catch(e){error.value=e.message}finally{saving.value=false}}
async function removeStep(s){if(!confirm('Delete “'+s.name+'” from this campaign?'))return;try{await api.deleteMessagingCampaignStep(selected.value.id,s.id);selected.value=await api.messagingCampaign(selected.value.id);await load()}catch(e){error.value=e.message}}
async function moveStep(s,direction){try{await api.moveMessagingCampaignStep(selected.value.id,s.id,direction);selected.value=await api.messagingCampaign(selected.value.id);await load()}catch(e){error.value=e.message}}
async function removeCampaign(c){if(!confirm('Delete campaign “'+c.name+'”?'))return;try{await api.deleteMessagingCampaign(c.id);if(selected.value?.id===c.id)selected.value=null;await load();success.value='Campaign deleted.'}catch(e){error.value=e.message}}
watch(()=>props.channel,()=>{selected.value=null;campaignOpen.value=false;stepOpen.value=false;load()})
onMounted(load)
</script>
<template>
<section class="campaign-engine">
  <div class="toolbar"><div><strong>Campaign workspace</strong><span>{{campaigns.length}} campaign{{campaigns.length===1?'':'s'}}</span></div><button class="primary" @click="newCampaign">+ New Campaign</button></div>
  <p v-if="error" class="notice error">{{error}}</p><p v-if="success" class="notice success">{{success}}</p>
  <div class="card">
    <div v-if="loading" class="empty">Loading campaigns…</div>
    <div v-else-if="!campaigns.length" class="empty"><strong>No {{channelLabel}} campaigns yet.</strong><p>Create a campaign, then add the messages that should run in sequence.</p></div>
    <template v-for="c in campaigns" :key="c.id">
      <div class="row" @click="openCampaign(c)"><div class="title"><strong>{{c.name}}</strong><small>{{c.description||'No description'}} · {{c.step_count}} step{{c.step_count===1?'':'s'}}</small></div><span class="pill">{{c.status}}</span><span>{{fmt(c.updated_at)}}</span><button v-if="c.status==='draft'" class="danger" @click.stop="removeCampaign(c)">Delete</button><button class="chev">{{selected?.id===c.id?'⌃':'⌄'}}</button></div>
      <div v-if="selected?.id===c.id" class="detail">
        <div class="detail-head"><div><h3>Campaign sequence</h3><p>Messages run from top to bottom. Each delay is measured from the previous step.</p></div><button class="primary" @click="newStep">+ Add message</button></div>
        <div v-if="!selected.steps?.length" class="empty inner">No messages yet. Add the first message to start building this campaign.</div>
        <div v-for="(s,i) in selected.steps" :key="s.id" class="step-card">
          <div class="step-num">{{i+1}}</div><div class="step-main"><div class="step-head"><strong>{{s.name}}</strong><span>{{delayLabel(s.delay_seconds)}}</span></div><div class="message">{{s.message_text}}</div><small v-if="s.media_url">{{s.media_type}} · {{s.media_url}}</small></div>
          <div class="step-actions"><button :disabled="i===0" @click="moveStep(s,'up')">↑</button><button :disabled="i===selected.steps.length-1" @click="moveStep(s,'down')">↓</button><button @click="editStep(s)">Edit</button><button class="danger" @click="removeStep(s)">Delete</button></div>
        </div>
        <div class="foundation-note"><strong>Campaign delivery foundation ready.</strong><span>Audience snapshotting, launch/scheduling and per-step recipient reporting are the next runtime layer.</span></div>
      </div>
    </template>
  </div>
  <div v-if="campaignOpen" class="overlay" @click.self="campaignOpen=false"><div class="modal"><div class="modal-head"><div><small>NEW {{channelLabel.toUpperCase()}} CAMPAIGN</small><h2>Create campaign</h2></div><button @click="campaignOpen=false">×</button></div><label>Campaign name<input v-model="form.name" placeholder="e.g. September re-engagement"></label><label>Description<textarea v-model="form.description" rows="3" placeholder="Optional internal description"></textarea></label><label>{{channelLabel}} account<select v-model="form.channel_account_id"><option value="" disabled>Select account…</option><option v-for="a in activeAccounts" :key="a.id" :value="a.id">{{accountName(a)}}</option></select></label><label>Audience<select v-model="form.audience_type"><option value="all">All eligible contacts</option><option value="filtered">Filtered audience (runtime layer next)</option></select></label><div class="actions"><button @click="campaignOpen=false">Cancel</button><button class="primary" :disabled="saving||!form.name.trim()||!form.channel_account_id" @click="saveCampaign">{{saving?'Saving…':'Create campaign'}}</button></div></div></div>
  <div v-if="stepOpen" class="overlay" @click.self="stepOpen=false"><div class="modal"><div class="modal-head"><div><small>CAMPAIGN MESSAGE</small><h2>{{editingStep?'Edit':'Add'}} message</h2></div><button @click="stepOpen=false">×</button></div><label>Step name<input v-model="step.name"></label><label>Delay after previous step<select v-model.number="step.delay_seconds"><option :value="0">Immediately</option><option :value="300">5 minutes</option><option :value="3600">1 hour</option><option :value="21600">6 hours</option><option :value="86400">1 day</option><option :value="172800">2 days</option><option :value="604800">7 days</option></select></label><label>Message<textarea v-model="step.message_text" rows="7" placeholder="Enter the message…"></textarea></label><div class="grid2"><label>Media URL<input v-model="step.media_url" placeholder="Optional"></label><label>Media type<select v-model="step.media_type"><option value="image">Image</option><option value="video">Video</option><option value="document">Document</option></select></label></div><p class="hint">Variables and provider-specific template controls will use the same field/template infrastructure as Broadcasts when campaign delivery is connected.</p><div class="actions"><button @click="stepOpen=false">Cancel</button><button class="primary" :disabled="saving||!step.name.trim()||!step.message_text.trim()" @click="saveStep">{{saving?'Saving…':'Save message'}}</button></div></div></div>
</section>
</template>
<style scoped>
.campaign-engine{margin:0 -38px;padding:8px 38px 60px}.toolbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px}.toolbar>div{display:flex;gap:12px;align-items:baseline}.toolbar span{color:#728078;font-size:13px}.primary{background:#111a2d;color:#fff;border:0;border-radius:7px;padding:10px 14px;font-weight:750;cursor:pointer}.card{background:#fff;border:1px solid #dce4e0;border-radius:14px;overflow:hidden}.row{display:grid;grid-template-columns:minmax(280px,1fr) 90px 180px auto 28px;align-items:center;gap:12px;padding:15px 18px;border-bottom:1px solid #e5ebe8;cursor:pointer}.title{display:flex;flex-direction:column}.title small{color:#708078;margin-top:3px}.pill{justify-self:start;background:#f0f3f2;border-radius:999px;padding:4px 9px;font-size:11px;font-weight:800;text-transform:capitalize}.danger{color:#c72c25;border:1px solid #efbbb7;background:#fff}.row button,.step-actions button,.actions button,.modal-head button{border-radius:7px;padding:7px 10px;border:1px solid #d5ded9;background:#fff;cursor:pointer}.chev{border:0!important}.detail{padding:18px 22px 24px;background:#fbfcfc;border-bottom:1px solid #dfe7e3}.detail-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px}.detail-head h3{margin:0}.detail-head p{margin:4px 0;color:#74837c;font-size:13px}.step-card{display:flex;gap:14px;align-items:flex-start;padding:14px;background:#fff;border:1px solid #dfe7e3;border-radius:10px;margin:9px 0}.step-num{width:30px;height:30px;border-radius:50%;background:#e7f5ed;color:#087743;display:grid;place-items:center;font-weight:800}.step-main{flex:1}.step-head{display:flex;gap:12px;align-items:center}.step-head span{font-size:12px;color:#73827a;background:#f2f5f3;padding:3px 7px;border-radius:999px}.message{white-space:pre-wrap;margin-top:8px}.step-main small{display:block;color:#74837c;margin-top:8px}.step-actions{display:flex;gap:5px}.step-actions button:disabled{opacity:.35}.foundation-note{display:flex;gap:8px;margin-top:16px;padding:12px;background:#f0f7f3;border-radius:8px;color:#496057;font-size:13px}.empty{padding:42px;text-align:center;color:#728078}.empty strong{color:#203128}.empty p{margin:6px 0}.empty.inner{padding:24px}.notice{margin:0 0 12px}.notice.error{color:#bd2922}.notice.success{color:#087b47}.overlay{position:fixed;inset:0;background:rgba(20,28,35,.52);display:grid;place-items:center;z-index:1000;padding:24px}.modal{width:min(620px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:14px;padding:20px;box-shadow:0 20px 60px rgba(0,0,0,.2)}.modal-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:16px}.modal-head small{color:#07804a;font-weight:800}.modal-head h2{margin:3px 0}.modal-head button{font-size:22px;border:0}.modal label{display:flex;flex-direction:column;gap:6px;font-weight:700;font-size:13px;margin:12px 0}.modal input,.modal textarea,.modal select{border:1px solid #cfd9d4;border-radius:8px;padding:10px;font:inherit;background:#fff}.grid2{display:grid;grid-template-columns:1fr 180px;gap:10px}.hint{font-size:12px;color:#718078;background:#f5f7f6;padding:10px;border-radius:7px}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.actions .primary{background:#111a2d;color:#fff}.actions button:disabled{opacity:.5}@media(max-width:900px){.campaign-engine{margin:0 -18px;padding:8px 18px}.row{grid-template-columns:1fr auto}.row>span:nth-of-type(2),.row>.danger{display:none}.step-card{flex-wrap:wrap}.step-actions{width:100%}.foundation-note{flex-direction:column}}
</style>
